            PrayerTermAnnotation(term = "remissão dos pecados", origin = "Remissão vem do latim remissio: perdão, liberação de uma dívida. É Deus quem reconcilia o pecador consigo por Cristo, e não uma simples decisão de esquecer o que aconteceu.", today = "Confio no perdão oferecido no Batismo e na Reconciliação, procuro reparar o dano possível e acolho um recomeço real.", scriptureQuote = null, scriptureReference = "João 20,22–23; Lucas 24,47", catechism = "Catecismo da Igreja Católica, 976–983"),
