    private fun prayer5() = TreasuryPrayer(
        id = "salve-rainha", title = "Salve Rainha", category = PrayerCategory.MARIAN,
        summary = "Esperança e intercessão no caminho para Cristo.", portuguese = "Salve, Rainha, Mãe de misericórdia, vida, doçura e esperança nossa, salve! A vós bradamos, os degredados filhos de Eva. A vós suspiramos, gemendo e chorando neste vale de lágrimas.\n\nEia, pois, advogada nossa, esses vossos olhos misericordiosos a nós volvei; e depois deste desterro, mostrai-nos Jesus, bendito fruto do vosso ventre. Ó clemente, ó piedosa, ó doce sempre Virgem Maria.\n\nRogai por nós, Santa Mãe de Deus, para que sejamos dignos das promessas de Cristo. Amém.",
        latinTitle = "Salve Regina", latin = "Salve, Regína, Mater misericórdiæ, vita, dulcédo et spes nostra, salve! Ad te clamámus, éxsules fílii Evæ. Ad te suspirámus, geméntes et flentes in hac lacrimárum valle. Eia ergo, advocáta nostra, illos tuos misericórdes óculos ad nos convérte; et Iesum, benedíctum fructum ventris tui, nobis post hoc exsílium osténde. O clemens, o pia, o dulcis Virgo María. Ora pro nobis, sancta Dei Génetrix, ut digni efficiámur promissiónibus Christi. Amen.",
        verses = listOf(
            BilingualVerse("Salve, Rainha, Mãe de misericórdia, vida, doçura e esperança nossa, salve!", "Salve, Regína, Mater misericórdiæ, vita, dulcédo et spes nostra, salve!", listOf(LatinGloss("Regína", "Rainha", null), LatinGloss("Mater misericórdiæ", "Mãe de misericórdia", null), LatinGloss("spes nostra", "esperança nossa", null))),
            BilingualVerse("A vós bradamos, os degredados filhos de Eva.", "Ad te clamámus, éxsules fílii Evæ.", listOf(LatinGloss("clamámus", "bradamos", null), LatinGloss("éxsules", "exilados", null), LatinGloss("fílii Evæ", "filhos de Eva", null))),
            BilingualVerse("A vós suspiramos, gemendo e chorando neste vale de lágrimas.", "Ad te suspirámus, geméntes et flentes in hac lacrimárum valle.", listOf(LatinGloss("geméntes et flentes", "gemendo e chorando", null), LatinGloss("lacrimárum valle", "vale de lágrimas", null))),
            BilingualVerse("Eia, pois, advogada nossa, esses vossos olhos misericordiosos a nós volvei;", "Eia ergo, advocáta nostra, illos tuos misericórdes óculos ad nos convérte;", listOf(LatinGloss("Eia ergo", "Eia pois", "Exclamação de súplica e confiança."), LatinGloss("advocáta nostra", "advogada nossa", null), LatinGloss("convérte", "volvei", null))),
            BilingualVerse("e depois deste desterro, mostrai-nos Jesus, bendito fruto do vosso ventre.", "et Iesum, benedíctum fructum ventris tui, nobis post hoc exsílium osténde.", listOf(LatinGloss("post hoc exsílium", "depois deste desterro", null), LatinGloss("osténde", "mostrai", null))),
            BilingualVerse("Ó clemente, ó piedosa, ó doce sempre Virgem Maria.", "O clemens, o pia, o dulcis Virgo María.", listOf(LatinGloss("clemens", "clemente", null), LatinGloss("pia", "piedosa", "Aqui: compassiva."), LatinGloss("dulcis", "doce", null))),
            BilingualVerse("Rogai por nós, Santa Mãe de Deus, para que sejamos dignos das promessas de Cristo. Amém.", "Ora pro nobis, sancta Dei Génetrix, ut digni efficiámur promissiónibus Christi. Amen.", listOf(LatinGloss("ut", "para que", null), LatinGloss("digni efficiámur", "sejamos feitos dignos", null), LatinGloss("promissiónibus Christi", "das promessas de Cristo", null))),
        ),
        annotations = listOf(
            PrayerTermAnnotation(term = "vale de lágrimas", origin = "A imagem aproxima a vida peregrina de um vale atravessado com sofrimento. O Salmo 84(83) fala de transformar um vale árido em lugar de fontes. A oração não declara má toda a criação.", today = "Posso levar a Deus o luto, a doença e a injustiça sem negar as alegrias. A esperança cristã me convida também a consolar quem atravessa esse vale.", scriptureQuote = null, scriptureReference = "Salmo 84(83),6–8; Apocalipse 21,4", catechism = "Catecismo da Igreja Católica, 1048–1050; 1818"),
            PrayerTermAnnotation(term = "advogada nossa", origin = "Advocata é quem é chamada para estar ao lado de alguém e interceder. Maria intercede em dependência total de Cristo: sua ação materna não concorre com a mediação única do Filho.", today = "Peço que Maria me acompanhe na conversão e me conduza a Jesus. Não imagino um Pai hostil que precise ser convencido a amar.", scriptureQuote = null, scriptureReference = "João 2,1–11; 1 João 2,1", catechism = "Catecismo da Igreja Católica, 969–970"),
            PrayerTermAnnotation(term = "degredados filhos de Eva", origin = "Degredado é exilado. A imagem recorda a humanidade ferida pelo pecado e peregrina em busca de sua pátria, não uma rejeição do corpo ou desprezo pelas mulheres.", today = "Reconheço minha necessidade de salvação sem perder a dignidade de criatura amada. Cristo, novo Adão, abre o caminho da comunhão.", scriptureQuote = null, scriptureReference = "Gênesis 3,23; Romanos 5,18–19", catechism = "Catecismo da Igreja Católica, 402–409; 411"),
            PrayerTermAnnotation(term = "clemente", origin = "Do latim clemens: misericordiosa, inclinada à compaixão. Na antífona, o adjetivo exprime confiança no cuidado materno de Maria recebido de Deus.", today = "Peço uma oração compassiva e aprendo a tratar com mansidão quem errou, sem chamar de bom o mal cometido.", scriptureQuote = null, scriptureReference = "Lucas 1,50; Colossenses 3,12–13", catechism = "Catecismo da Igreja Católica, 971; 2447"),
        ),
        source = "Compêndio do Catecismo da Igreja Católica, apêndice de orações comuns. Versículo final tradicional acrescentado; “sempre” não tem palavra correspondente nesta antífona latina. Correção de “posi” para “post”.", context = "Antífona mariana medieval. As imagens de exílio e lágrimas expressam a necessidade humana de salvação e terminam apontando para Jesus, fruto bendito de Maria.",
        sourceUrls = listOf("https://www.vatican.va/archive/compendium_ccc/documents/archive_2005_compendium-ccc_po.html"),
        keywords = listOf(),
        fixedPrayer = com.sertumrosarum.domain.prayer.FixedPrayer.HAIL_HOLY_QUEEN,
        latinSolo = null,
    )
    private fun prayer6() = TreasuryPrayer(
        id = "o-meu-jesus", title = "Ó meu Jesus", category = PrayerCategory.DISTRESS,
        summary = "A jaculatória de Fátima após cada dezena.", portuguese = "Ó meu Jesus, perdoai-nos, livrai-nos do fogo do inferno, levai as almas todas para o Céu e socorrei principalmente as que mais precisarem da vossa misericórdia.",
        latinTitle = "O mi Iesu", latin = "O mi Iesu, dimítte nobis débita nostra, líbera nos ab igne inférni, perduc in cælum omnes ánimas, præsértim illas quæ máxime índigent misericórdia tua.",
        verses = listOf(
            BilingualVerse("Ó meu Jesus, perdoai-nos,", "O mi Iesu, dimítte nobis débita nostra,", listOf(LatinGloss("O mi Iesu", "Ó meu Jesus", null), LatinGloss("dimítte nobis", "perdoai-nos", null))),
            BilingualVerse("livrai-nos do fogo do inferno,", "líbera nos ab igne inférni,", listOf(LatinGloss("líbera nos", "livrai-nos", null), LatinGloss("ab igne inférni", "do fogo do inferno", null))),
            BilingualVerse("levai as almas todas para o Céu", "perduc in cælum omnes ánimas,", listOf(LatinGloss("perduc", "conduzi", null), LatinGloss("omnes ánimas", "todas as almas", null))),
            BilingualVerse("e socorrei principalmente as que mais precisarem da vossa misericórdia.", "præsértim illas quæ máxime índigent misericórdia tua.", listOf(LatinGloss("præsértim", "principalmente", null), LatinGloss("índigent", "necessitam", null), LatinGloss("misericórdia tua", "de vossa misericórdia", null))),
        ),
        annotations = listOf(
            PrayerTermAnnotation(term = "vossa misericórdia", origin = "Misericórdia é o amor de Deus que vem ao encontro da miséria humana. Na oração de Fátima, o pedido se estende a todos e especialmente a quem mais necessita.", today = "Não seleciono quem merece minha intercessão. Peço conversão, salvação e socorro, confiando na justiça e no amor de Deus.", scriptureQuote = null, scriptureReference = "Lucas 15,11–32; 1 Timóteo 2,1–4", catechism = "Catecismo da Igreja Católica, 1846–1848; 67"),
        ),
        source = "Fórmula devocional tradicional; pontuação e ortografia adaptadas ao português do Brasil. Versão latina devocional de uso corrente; não integra o apêndice do Compêndio.", context = "Fórmula devocional ligada às aparições de Fátima. Uma revelação privada pode ajudar a viver o Evangelho, mas não acrescenta algo à Revelação definitiva de Cristo.",
        sourceUrls = listOf(),
        keywords = listOf(),
        fixedPrayer = com.sertumrosarum.domain.prayer.FixedPrayer.FATIMA,
        latinSolo = null,
    )
    private fun prayer7() = TreasuryPrayer(
        id = "oferecimento-do-terco", title = "Oferecimento do Terço", category = PrayerCategory.WAKING,
        summary = "Dedicar a contemplação dos mistérios a Jesus.", portuguese = "Divino Jesus, nós Vos oferecemos este terço que vamos rezar, contemplando os mistérios da nossa Redenção. Concedei-nos, por intercessão da Virgem Maria, Mãe de Deus e nossa Mãe, as virtudes que nos são necessárias para bem rezá-lo e a graça de ganharmos as indulgências desta santa devoção.",
        latinTitle = "Oblatio Rosarii", latin = "Divíne Iesu, tibi offérimus hoc rosárium quod recitatúri sumus, mystéria nostræ redemptiónis contemplántes. Concéde nobis, intercedénte Vírgine María, Matre Dei et Matre nostra, virtútes ad illud pie recitándum necessárias et grátiam indulgéntias huius sanctæ devotiónis consequéndi.",
        verses = listOf(
            BilingualVerse("Divino Jesus, nós Vos oferecemos este terço que vamos rezar, contemplando os mistérios da nossa Redenção.", "Divíne Iesu, tibi offérimus hoc rosárium quod recitatúri sumus, mystéria nostræ redemptiónis contemplántes.", listOf(LatinGloss("tibi offérimus", "a vós oferecemos", null), LatinGloss("redemptiónis", "da redenção", null))),
            BilingualVerse("Concedei-nos, por intercessão da Virgem Maria, Mãe de Deus e nossa Mãe, as virtudes que nos são necessárias para bem rezá-lo e a graça de ganharmos as indulgências desta santa devoção.", "Concéde nobis, intercedénte Vírgine María, Matre Dei et Matre nostra, virtútes ad illud pie recitándum necessárias et grátiam indulgéntias huius sanctæ devotiónis consequéndi.", listOf(LatinGloss("Concéde nobis", "concedei-nos", null), LatinGloss("intercedénte", "por intercessão", "Literalmente: intercedendo."), LatinGloss("virtútes", "virtudes", null))),
        ),
        annotations = listOf(
            PrayerTermAnnotation(term = "indulgências", origin = "A indulgência é a remissão, diante de Deus, da pena temporal de pecados cuja culpa já foi perdoada. Está ligada à comunhão dos santos e à aplicação dos frutos da redenção de Cristo.", today = "Rezo com arrependimento, caridade e disposição para a Reconciliação. Não trato a oração como contagem que obriga Deus ou como licença para pecar.", scriptureQuote = null, scriptureReference = "Mateus 16,19; Colossenses 1,24", catechism = "Catecismo da Igreja Católica, 1471–1479"),
        ),
        source = "Fórmula devocional tradicional; pontuação e ortografia adaptadas ao português do Brasil. Tradução latina editorial do Sertum; não apresentada como fórmula litúrgica oficial.", context = "O oferecimento exprime a intenção com que rezamos. As indulgências não compram o perdão nem dispensam conversão; supõem uma vida reconciliada e as condições indicadas pela Igreja.",
        sourceUrls = listOf(),
        keywords = listOf(),
        fixedPrayer = com.sertumrosarum.domain.prayer.FixedPrayer.OFFERING,
        latinSolo = "Divíne Iesu, tibi óffero hoc rosárium quod recitábo, mystéria nostræ redemptiónis contémplans. Concéde mihi, intercedénte Vírgine María, Matre Dei et Matre mea, virtútes ad illud pie recitándum necessárias et grátiam indulgéntias huius sanctæ devotiónis consequéndi.",
    )
    private fun prayer8() = TreasuryPrayer(
        id = "infinitas-gracas", title = "Infinitas Graças", category = PrayerCategory.THANKSGIVING,
        summary = "A gratidão que encerra a coroa de rosas.", portuguese = "Infinitas graças vos damos, soberana Rainha, pelos benefícios que todos os dias recebemos de vossas mãos liberais. Dignai-vos, agora e para sempre, tomar-nos debaixo do vosso poderoso amparo e, para mais vos obrigar, vos saudamos com uma Salve Rainha.",
        latinTitle = "Gratiarum actio", latin = "Infínitas tibi grátias ágimus, Regína, pro benefíciis quæ cotídie de mánibus tuis largis accípimus. Dignáre nunc et semper nos sub poténti præsídio tuo recípere; et ut te magis ad opem feréndam moveámus, te salutámus oratióne Salve Regína.",
        verses = listOf(
            BilingualVerse("Infinitas graças vos damos, soberana Rainha, pelos benefícios que todos os dias recebemos de vossas mãos liberais.", "Infínitas tibi grátias ágimus, Regína, pro benefíciis quæ cotídie de mánibus tuis largis accípimus.", listOf(LatinGloss("grátias ágimus", "damos graças", null), LatinGloss("cotídie", "todos os dias", null), LatinGloss("largis", "generosas", null))),
            BilingualVerse("Dignai-vos, agora e para sempre, tomar-nos debaixo do vosso poderoso amparo e, para mais vos obrigar, vos saudamos com uma Salve Rainha.", "Dignáre nunc et semper nos sub poténti præsídio tuo recípere; et ut te magis ad opem feréndam moveámus, te salutámus oratióne Salve Regína.", listOf(LatinGloss("Dignáre", "dignai-vos", null), LatinGloss("præsídio", "amparo", null), LatinGloss("opem feréndam", "prestar auxílio", null))),
        ),
        annotations = listOf(
            PrayerTermAnnotation(term = "mãos liberais", origin = "Liberal, neste uso antigo, significa generoso, abundante ao dar; não é uma posição política. A imagem das mãos recorda um cuidado que transmite os dons de Deus.", today = "Agradeço a Deus pelos dons recebidos e pela intercessão de Maria. Pergunto como minhas próprias mãos podem ser mais abertas a quem precisa.", scriptureQuote = null, scriptureReference = "Lucas 1,46–55; 2 Coríntios 9,7–8", catechism = "Catecismo da Igreja Católica, 2637–2638; 970"),
            PrayerTermAnnotation(term = "para mais vos obrigar", origin = "É uma maneira antiga de pedir uma atenção favorável, como quem insiste confiante diante de uma mãe. Não significa impor uma dívida a Maria ou controlar a ação de Deus.", today = "Rezo com liberdade filial, sem negociar favores ou prometer que uma fórmula produzirá resultados. A confiança pode conviver com uma resposta diferente da esperada.", scriptureQuote = null, scriptureReference = "Lucas 11,5–13", catechism = "Catecismo da Igreja Católica, 2734–2741"),
        ),
        source = "Fórmula devocional tradicional; pontuação e ortografia adaptadas ao português do Brasil. Tradução latina editorial do Sertum; “para mais vos obrigar” é uma súplica filial, não coação.", context = "A linguagem antiga dirige a Maria um agradecimento por sua intercessão. Todo dom tem sua fonte em Deus; “obrigar” exprime aqui um apelo filial, nunca poder de controlar a graça.",
        sourceUrls = listOf(),
        keywords = listOf(),
        fixedPrayer = com.sertumrosarum.domain.prayer.FixedPrayer.THANKSGIVING,
        latinSolo = "Infínitas tibi grátias ago, Regína, pro benefíciis quæ cotídie de mánibus tuis largis accípio. Dignáre nunc et semper me sub poténti præsídio tuo recípere; et ut te magis ad opem feréndam móveam, te salúto oratióne Salve Regína.",
    )
    private fun prayer9() = TreasuryPrayer(
        id = "sob-a-vossa-protecao", title = "Sob a vossa proteção", category = PrayerCategory.NIGHT,
        summary = "A antiga antífona Sub tuum praesidium.", portuguese = "À vossa proteção recorremos, Santa Mãe de Deus; não desprezeis as nossas súplicas em nossas necessidades; mas livrai-nos de todos os perigos, ó Virgem gloriosa e bendita.",
        latinTitle = "Sub tuum præsidium", latin = "Sub tuum præsídium confúgimus, sancta Dei Génetrix; nostras deprecatiónes ne despícias in necessitátibus; sed a perículis cunctis líbera nos semper, Virgo gloriósa et benedícta.",
        verses = listOf(
            BilingualVerse("À vossa proteção recorremos, Santa Mãe de Deus;", "Sub tuum præsídium confúgimus, sancta Dei Génetrix;", listOf(LatinGloss("Sub tuum præsídium", "à vossa proteção", null), LatinGloss("confúgimus", "recorremos", "Literalmente: buscamos refúgio."), LatinGloss("Dei Génetrix", "Mãe de Deus", null))),
            BilingualVerse("não desprezeis as nossas súplicas em nossas necessidades;", "nostras deprecatiónes ne despícias in necessitátibus;", listOf(LatinGloss("deprecatiónes", "súplicas", null), LatinGloss("ne despícias", "não desprezeis", null))),
            BilingualVerse("mas livrai-nos de todos os perigos, ó Virgem gloriosa e bendita.", "sed a perículis cunctis líbera nos semper, Virgo gloriósa et benedícta.", listOf(LatinGloss("a perículis cunctis", "de todos os perigos", null), LatinGloss("semper", "sempre", "Explícito no latim, implícito no pedido português."))),
        ),
        annotations = listOf(
            PrayerTermAnnotation(term = "proteção", origin = "Praesidium designa defesa, auxílio e lugar de refúgio. Nesta antífona, a proteção de Maria é a de uma mãe que intercede diante de Deus, não uma força separada de Cristo.", today = "Entrego o medo à oração e busco os meios de cuidado disponíveis. A devoção não me pede que permaneça numa situação de violência ou perigo.", scriptureQuote = null, scriptureReference = "João 19,26–27; Salmo 46(45),2", catechism = "Catecismo da Igreja Católica, 969–970; 2679"),
            PrayerTermAnnotation(term = "súplicas", origin = "Súplica é um pedido humilde e insistente. A palavra latina deprecatio sublinha a condição de quem necessita de auxílio e se dirige a outro com confiança.", today = "Posso nomear minha necessidade sem fingir autossuficiência. Pedir ajuda a Deus e às pessoas não diminui minha fé.", scriptureQuote = null, scriptureReference = "Filipenses 4,6–7; Hebreus 4,16", catechism = "Catecismo da Igreja Católica, 2629–2633"),
        ),
        source = "Compêndio do Catecismo da Igreja Católica, apêndice de orações comuns. Ortografia adaptada ao Brasil; “sempre” está explícito somente no latim.", context = "Uma das mais antigas invocações marianas conservadas. Pede intercessão em meio ao perigo; a confiança não dispensa procurar proteção concreta quando necessário.",
        sourceUrls = listOf("https://www.vatican.va/archive/compendium_ccc/documents/archive_2005_compendium-ccc_po.html"),
        keywords = listOf(),
        fixedPrayer = null,
        latinSolo = null,
    )
    private fun prayer10() = TreasuryPrayer(
        id = "alma-de-cristo", title = "Alma de Cristo", category = PrayerCategory.COMMUNION,
        summary = "Permanecer unido a Jesus depois da comunhão.", portuguese = "Alma de Cristo, santificai-me. Corpo de Cristo, salvai-me. Sangue de Cristo, inebriai-me. Água do lado de Cristo, lavai-me. Paixão de Cristo, confortai-me. Ó bom Jesus, ouvi-me. Dentro das vossas chagas, escondei-me. Não permitais que eu me separe de vós. Do inimigo maligno, defendei-me. Na hora da minha morte, chamai-me. E mandai-me ir para vós, para que vos louve com os vossos santos, pelos séculos dos séculos. Amém.",
        latinTitle = "Anima Christi", latin = "Ánima Christi, sanctífica me. Corpus Christi, salva me. Sanguis Christi, inébria me. Aqua láteris Christi, lava me. Pássio Christi, confórta me. O bone Iesu, exáudi me. Intra tua vúlnera abscónde me. Ne permíttas me separári a te. Ab hoste malígno defénde me. In hora mortis meæ voca me. Et iube me veníre ad te, ut cum sanctis tuis laudem te in sǽcula sæculórum. Amen.",
        verses = listOf(
            BilingualVerse("Alma de Cristo, santificai-me.", "Ánima Christi, sanctífica me.", listOf(LatinGloss("Ánima", "alma", null), LatinGloss("sanctífica me", "santificai-me", null))),
            BilingualVerse("Corpo de Cristo, salvai-me.", "Corpus Christi, salva me.", listOf(LatinGloss("Corpus", "corpo", null), LatinGloss("salva me", "salvai-me", null))),
            BilingualVerse("Sangue de Cristo, inebriai-me.", "Sanguis Christi, inébria me.", listOf(LatinGloss("Sanguis", "sangue", null), LatinGloss("inébria me", "inebriai-me", "Imagem da plenitude do amor, não de embriaguez física."))),
            BilingualVerse("Água do lado de Cristo, lavai-me.", "Aqua láteris Christi, lava me.", listOf(LatinGloss("láteris", "do lado", null), LatinGloss("lava me", "lavai-me", null))),
            BilingualVerse("Paixão de Cristo, confortai-me.", "Pássio Christi, confórta me.", listOf(LatinGloss("Pássio", "paixão", "O sofrimento e a entrega de Cristo."), LatinGloss("confórta me", "fortalecei-me", null))),
            BilingualVerse("Ó bom Jesus, ouvi-me.", "O bone Iesu, exáudi me.", listOf(LatinGloss("bone Iesu", "bom Jesus", "Vocativo: chamamento."), LatinGloss("exáudi me", "ouvi-me", null))),
            BilingualVerse("Dentro das vossas chagas, escondei-me.", "Intra tua vúlnera abscónde me.", listOf(LatinGloss("Intra", "dentro de", null), LatinGloss("vúlnera", "chagas", null), LatinGloss("abscónde me", "escondei-me", null))),
            BilingualVerse("Não permitais que eu me separe de vós.", "Ne permíttas me separári a te.", listOf(LatinGloss("Ne permíttas", "não permitais", null), LatinGloss("separári", "ser separado", null))),
            BilingualVerse("Do inimigo maligno, defendei-me.", "Ab hoste malígno defénde me.", listOf(LatinGloss("Ab hoste malígno", "do inimigo maligno", null), LatinGloss("defénde me", "defendei-me", null))),
            BilingualVerse("Na hora da minha morte, chamai-me.", "In hora mortis meæ voca me.", listOf(LatinGloss("mortis meæ", "de minha morte", null), LatinGloss("voca me", "chamai-me", null))),
            BilingualVerse("E mandai-me ir para vós, para que vos louve com os vossos santos, pelos séculos dos séculos. Amém.", "Et iube me veníre ad te, ut cum sanctis tuis laudem te in sǽcula sæculórum. Amen.", listOf(LatinGloss("iube", "mandai", null), LatinGloss("veníre ad te", "ir a vós", null), LatinGloss("laudem te", "eu vos louve", null))),
        ),
        annotations = listOf(
            PrayerTermAnnotation(term = "inebriai-me", origin = "O verbo latino inebriare é usado como imagem de abundância que transborda. Aqui aponta para a vida recebida de Cristo, não para o uso de álcool ou a perda de consciência.", today = "Peço que o amor de Jesus transforme meus afetos e escolhas. A comunhão me chama à lucidez e à caridade, não à fuga da realidade.", scriptureQuote = null, scriptureReference = "Salmo 23(22),5; Efésios 5,18–20", catechism = "Catecismo da Igreja Católica, 1391–1395"),
            PrayerTermAnnotation(term = "chagas", origin = "Chaga é ferida. As feridas do Ressuscitado mostram que o vencedor da morte é o mesmo que foi crucificado; sua glória não apaga a história de seu amor.", today = "Procuro abrigo na entrega de Cristo. Não busco sofrimento por si mesmo: levo a ele minhas feridas e me aproximo com cuidado das feridas alheias.", scriptureQuote = null, scriptureReference = "João 20,24–29; 1 Pedro 2,24", catechism = "Catecismo da Igreja Católica, 645; 1505"),
            PrayerTermAnnotation(term = "santificai-me", origin = "Santificar é tornar participante da santidade de Deus. A Eucaristia aumenta a união com Cristo e fortalece a caridade; não é um objeto mágico.", today = "Peço coerência entre o que recebi no altar e minhas atitudes. Posso escolher hoje um gesto de reconciliação ou serviço.", scriptureQuote = null, scriptureReference = "João 6,56; 1 Coríntios 10,16–17", catechism = "Catecismo da Igreja Católica, 1391–1397; 2013"),
        ),
        source = "Compêndio do Catecismo da Igreja Católica, apêndice de orações comuns. Ortografia e pontuação adaptadas ao português do Brasil.", context = "Oração medieval de união com Cristo, difundida nos Exercícios Espirituais de Santo Inácio; ele não é seu autor comprovado. Pode ser rezada após a comunhão ou em adoração.",
