    private fun prayer11() = TreasuryPrayer(
        id = "magnificat", title = "Magnificat", category = PrayerCategory.THANKSGIVING,
        summary = "Com Maria, reconhecer as maravilhas de Deus.", portuguese = "A minha alma glorifica ao Senhor, e o meu espírito se alegra em Deus, meu Salvador. Porque pôs os olhos na humildade da sua serva: de hoje em diante me chamarão bem-aventurada todas as gerações. O Todo-Poderoso fez em mim maravilhas: santo é o seu nome. A sua misericórdia se estende de geração em geração sobre aqueles que o temem. Manifestou o poder do seu braço e dispersou os soberbos. Derrubou os poderosos de seus tronos e exaltou os humildes. Aos famintos encheu de bens e aos ricos despediu de mãos vazias. Acolheu Israel, seu servo, lembrado da sua misericórdia, como tinha prometido a nossos pais, a Abraão e à sua descendência para sempre. Glória ao Pai e ao Filho e ao Espírito Santo. Como era no princípio, agora e sempre. Amém.",
        latinTitle = "Magnificat", latin = "Magníficat ánima mea Dóminum, et exsultávit spíritus meus in Deo salvatóre meo, quia respéxit humilitátem ancíllæ suæ. Ecce enim ex hoc beátam me dicent omnes generatiónes, quia fecit mihi magna qui potens est, et sanctum nomen eius, et misericórdia eius in progénies et progénies timéntibus eum. Fecit poténtiam in bráchio suo, dispérsit supérbos mente cordis sui; depósuit poténtes de sede et exaltávit húmiles. Esuriéntes implévit bonis et dívites dimísit inánes. Suscépit Ísrael púerum suum, recordátus misericórdiæ, sicut locútus est ad patres nostros, Ábraham et sémini eius in sǽcula. Glória Patri et Fílio et Spirítui Sancto. Sicut erat in princípio, et nunc et semper, et in sǽcula sæculórum. Amen.",
        verses = listOf(
            BilingualVerse("A minha alma glorifica ao Senhor,", "Magníficat ánima mea Dóminum,", listOf(LatinGloss("Magníficat", "glorifica", "Literalmente: engrandece."), LatinGloss("ánima mea", "minha alma", null))),
            BilingualVerse("e o meu espírito se alegra em Deus, meu Salvador.", "et exsultávit spíritus meus in Deo salvatóre meo,", listOf(LatinGloss("exsultávit", "exultou", "A tradução portuguesa exprime o louvor no presente."), LatinGloss("salvatóre meo", "meu Salvador", null))),
            BilingualVerse("Porque pôs os olhos na humildade da sua serva: de hoje em diante me chamarão bem-aventurada todas as gerações.", "quia respéxit humilitátem ancíllæ suæ. Ecce enim ex hoc beátam me dicent omnes generatiónes,", listOf(LatinGloss("ancíllæ suæ", "de sua serva", null), LatinGloss("beátam", "bem-aventurada", null), LatinGloss("omnes generatiónes", "todas as gerações", null))),
            BilingualVerse("O Todo-Poderoso fez em mim maravilhas: santo é o seu nome.", "quia fecit mihi magna qui potens est, et sanctum nomen eius,", listOf(LatinGloss("fecit mihi magna", "fez para mim grandes coisas", null), LatinGloss("sanctum", "santo", null))),
            BilingualVerse("A sua misericórdia se estende de geração em geração sobre aqueles que o temem.", "et misericórdia eius in progénies et progénies timéntibus eum.", listOf(LatinGloss("timéntibus eum", "àqueles que o temem", "Temor filial: reverência amorosa."))),
            BilingualVerse("Manifestou o poder do seu braço e dispersou os soberbos.", "Fecit poténtiam in bráchio suo, dispérsit supérbos mente cordis sui;", listOf(LatinGloss("bráchio suo", "seu braço", "Imagem bíblica do poder de agir."), LatinGloss("supérbos", "soberbos", null))),
            BilingualVerse("Derrubou os poderosos de seus tronos e exaltou os humildes.", "depósuit poténtes de sede et exaltávit húmiles.", listOf(LatinGloss("depósuit", "derrubou", null), LatinGloss("exaltávit húmiles", "exaltou os humildes", null))),
            BilingualVerse("Aos famintos encheu de bens e aos ricos despediu de mãos vazias.", "Esuriéntes implévit bonis et dívites dimísit inánes.", listOf(LatinGloss("Esuriéntes", "os famintos", null), LatinGloss("bonis", "de bens", null), LatinGloss("inánes", "vazios", null))),
            BilingualVerse("Acolheu Israel, seu servo, lembrado da sua misericórdia,", "Suscépit Ísrael púerum suum, recordátus misericórdiæ,", listOf(LatinGloss("Suscépit", "acolheu", null), LatinGloss("recordátus", "lembrado", null))),
            BilingualVerse("como tinha prometido a nossos pais, a Abraão e à sua descendência para sempre.", "sicut locútus est ad patres nostros, Ábraham et sémini eius in sǽcula.", listOf(LatinGloss("sémini eius", "à sua descendência", "Literalmente: à sua semente."))),
            BilingualVerse("Glória ao Pai e ao Filho e ao Espírito Santo.", "Glória Patri et Fílio et Spirítui Sancto.", listOf(LatinGloss("Patri", "ao Pai", null), LatinGloss("Fílio", "ao Filho", null))),
            BilingualVerse("Como era no princípio, agora e sempre. Amém.", "Sicut erat in princípio, et nunc et semper, et in sǽcula sæculórum. Amen.", listOf(LatinGloss("semper", "sempre", null), LatinGloss("in sǽcula sæculórum", "pelos séculos dos séculos", null))),
        ),
        annotations = listOf(
            PrayerTermAnnotation(term = "humildade da sua serva", origin = "Ancilla significa serva; tapeínōsis, no texto grego, pode indicar a condição humilde e pequena. Maria reconhece a iniciativa do Senhor e responde livremente ao chamado.", today = "Não confundo humildade com desprezo por mim. Recebo meus dons com gratidão e os coloco a serviço sem precisar ocupar o centro.", scriptureQuote = null, scriptureReference = "Lucas 1,48; 1,38", catechism = "Catecismo da Igreja Católica, 489; 722"),
            PrayerTermAnnotation(term = "aqueles que o temem", origin = "O temor do Senhor, na linguagem bíblica, é reverência diante de sua santidade e confiança que evita ofendê-lo. Não é pânico de um Deus arbitrário.", today = "Trato Deus e as pessoas com respeito. Posso aproximar-me do Pai com confiança e, ao mesmo tempo, levar a sério minhas escolhas.", scriptureQuote = null, scriptureReference = "Salmo 103(102),13–18; Romanos 8,15", catechism = "Catecismo da Igreja Católica, 1831; 1828"),
            PrayerTermAnnotation(term = "exaltou os humildes", origin = "O cântico retoma a esperança dos pequenos de Israel e o cântico de Ana. A justiça de Deus desmascara a autossuficiência e acolhe quem não tem poder.", today = "A gratidão pede atenção a quem fica sem voz. Escolho partilhar recursos, ouvir com respeito e não medir o valor de alguém por seu prestígio.", scriptureQuote = null, scriptureReference = "1 Samuel 2,1–10; Lucas 1,52", catechism = "Catecismo da Igreja Católica, 2619; 2443–2449"),
        ),
        source = "Compêndio do Catecismo da Igreja Católica, apêndice de orações comuns. Lucas 1,46–55, seguido da doxologia. Ortografia adaptada; não constitui uma edição bíblica independente.", context = "Cântico de Maria em Lucas 1,46–55, usado nas Vésperas. A inversão entre poderosos e humildes anuncia a justiça de Deus e convida a uma gratidão que se torna solidariedade.",
        sourceUrls = listOf("https://www.vatican.va/archive/compendium_ccc/documents/archive_2005_compendium-ccc_po.html"),
