    private fun prayer12() = TreasuryPrayer(
        id = "regina-caeli", title = "Rainha do Céu", category = PrayerCategory.MARIAN,
        summary = "A alegria da Ressurreição no tempo pascal.", portuguese = "Rainha do Céu, alegrai-vos, aleluia! Porque aquele que merecestes trazer em vosso seio, aleluia! Ressuscitou como disse, aleluia! Rogai por nós a Deus, aleluia! Alegrai-vos e exultai, ó Virgem Maria, aleluia! Porque o Senhor ressuscitou verdadeiramente, aleluia! Oremos. Ó Deus, que alegrastes o mundo com a ressurreição de vosso Filho, nosso Senhor Jesus Cristo, concedei-nos, pela intercessão da Virgem Maria, sua Mãe, as alegrias da vida eterna. Por Cristo, nosso Senhor. Amém.",
        latinTitle = "Regina Cæli", latin = "Regína cæli, lætáre, allelúia! Quia quem meruísti portáre, allelúia! Resurréxit sicut dixit, allelúia! Ora pro nobis Deum, allelúia! Gaude et lætáre, Virgo María, allelúia! Quia surréxit Dóminus vere, allelúia! Orémus. Deus, qui per resurrectiónem Fílii tui Dómini nostri Iesu Christi mundum lætificáre dignátus es, præsta, quǽsumus, ut per eius Genetrícem Vírginem Maríam perpétuæ capiámus gáudia vitæ. Per Christum Dóminum nostrum. Amen.",
        verses = listOf(
            BilingualVerse("Rainha do Céu, alegrai-vos, aleluia!", "Regína cæli, lætáre, allelúia!", listOf(LatinGloss("Regína cæli", "Rainha do Céu", null), LatinGloss("lætáre", "alegrai-vos", null))),
            BilingualVerse("Porque aquele que merecestes trazer em vosso seio, aleluia!", "Quia quem meruísti portáre, allelúia!", listOf(LatinGloss("quem", "aquele que", null), LatinGloss("portáre", "trazer", null))),
            BilingualVerse("Ressuscitou como disse, aleluia!", "Resurréxit sicut dixit, allelúia!", listOf(LatinGloss("Resurréxit", "ressuscitou", null), LatinGloss("sicut dixit", "como disse", null))),
            BilingualVerse("Rogai por nós a Deus, aleluia!", "Ora pro nobis Deum, allelúia!", listOf(LatinGloss("Ora", "rogai", null), LatinGloss("pro nobis", "por nós", null))),
            BilingualVerse("Alegrai-vos e exultai, ó Virgem Maria, aleluia!", "Gaude et lætáre, Virgo María, allelúia!", listOf(LatinGloss("Gaude et lætáre", "alegrai-vos e exultai", null))),
            BilingualVerse("Porque o Senhor ressuscitou verdadeiramente, aleluia!", "Quia surréxit Dóminus vere, allelúia!", listOf(LatinGloss("Dóminus", "o Senhor", null), LatinGloss("vere", "verdadeiramente", null))),
            BilingualVerse("Oremos. Ó Deus, que alegrastes o mundo com a ressurreição de vosso Filho, nosso Senhor Jesus Cristo, concedei-nos, pela intercessão da Virgem Maria, sua Mãe, as alegrias da vida eterna. Por Cristo, nosso Senhor. Amém.", "Orémus. Deus, qui per resurrectiónem Fílii tui Dómini nostri Iesu Christi mundum lætificáre dignátus es, præsta, quǽsumus, ut per eius Genetrícem Vírginem Maríam perpétuæ capiámus gáudia vitæ. Per Christum Dóminum nostrum. Amen.", listOf(LatinGloss("Orémus", "oremos", null), LatinGloss("præsta, quǽsumus", "concedei, nós vos pedimos", null), LatinGloss("gáudia vitæ", "as alegrias da vida", null))),
        ),
        annotations = listOf(
            PrayerTermAnnotation(term = "aleluia", origin = "Do hebraico hallelū-Yāh: “louvai o Senhor”. A aclamação exprime alegria e louvor, especialmente na celebração pascal.", today = "A alegria da Ressurreição não exige esconder a tristeza. Posso louvar em esperança, confiando que a morte não tem a última palavra.", scriptureQuote = null, scriptureReference = "Salmo 150; Apocalipse 19,1–6", catechism = "Catecismo da Igreja Católica, 2641; 638–655"),
        ),
        source = "Compêndio do Catecismo da Igreja Católica, apêndice de orações comuns. Redação portuguesa adaptada; correção latina de “quelli” para “quem”.", context = "O Regina Caeli costuma substituir o Angelus no tempo pascal. O centro do júbilo é a ressurreição de Jesus, anunciada a Maria e a toda a Igreja.",
        sourceUrls = listOf("https://www.vatican.va/archive/compendium_ccc/documents/archive_2005_compendium-ccc_po.html"),
        keywords = listOf(),
        fixedPrayer = null,
        latinSolo = null,
    )
    private fun prayer13() = TreasuryPrayer(
        id = "angelus", title = "Angelus", category = PrayerCategory.WAKING,
        summary = "Recordar a Encarnação no ritmo do dia.", portuguese = "O Anjo do Senhor anunciou a Maria. E ela concebeu do Espírito Santo. Ave-Maria. Eis aqui a serva do Senhor. Faça-se em mim segundo a vossa palavra. Ave-Maria. E o Verbo se fez carne. E habitou entre nós. Ave-Maria. Rogai por nós, Santa Mãe de Deus, para que sejamos dignos das promessas de Cristo. Oremos. Infundi, Senhor, em nossas almas a vossa graça, para que nós, que pela anunciação do Anjo conhecemos a encarnação de Cristo, vosso Filho, pela sua paixão e cruz sejamos conduzidos à glória da ressurreição. Por Cristo, nosso Senhor. Amém.",
        latinTitle = "Angelus Domini", latin = "Ángelus Dómini nuntiávit Maríæ. Et concépit de Spíritu Sancto. Ave María. Ecce ancílla Dómini. Fiat mihi secúndum verbum tuum. Ave María. Et Verbum caro factum est. Et habitávit in nobis. Ave María. Ora pro nobis, sancta Dei Génetrix, ut digni efficiámur promissiónibus Christi. Orémus. Grátiam tuam, quǽsumus, Dómine, méntibus nostris infúnde; ut qui, Ángelo nuntiánte, Christi Fílii tui incarnatiónem cognóvimus, per passiónem eius et crucem ad resurrectiónis glóriam perducámur. Per eúndem Christum Dóminum nostrum. Amen.",
        verses = listOf(
            BilingualVerse("O Anjo do Senhor anunciou a Maria. E ela concebeu do Espírito Santo. Ave-Maria.", "Ángelus Dómini nuntiávit Maríæ. Et concépit de Spíritu Sancto. Ave María.", listOf(LatinGloss("Ángelus Dómini", "o Anjo do Senhor", null), LatinGloss("nuntiávit", "anunciou", null))),
            BilingualVerse("Eis aqui a serva do Senhor. Faça-se em mim segundo a vossa palavra. Ave-Maria.", "Ecce ancílla Dómini. Fiat mihi secúndum verbum tuum. Ave María.", listOf(LatinGloss("Ecce", "eis", null), LatinGloss("ancílla", "serva", null), LatinGloss("Fiat mihi", "faça-se em mim", null))),
            BilingualVerse("E o Verbo se fez carne. E habitou entre nós. Ave-Maria.", "Et Verbum caro factum est. Et habitávit in nobis. Ave María.", listOf(LatinGloss("Verbum", "Verbo", "A Palavra eterna de Deus."), LatinGloss("caro factum est", "fez-se carne", null), LatinGloss("habitávit in nobis", "habitou entre nós", null))),
            BilingualVerse("Rogai por nós, Santa Mãe de Deus, para que sejamos dignos das promessas de Cristo.", "Ora pro nobis, sancta Dei Génetrix, ut digni efficiámur promissiónibus Christi.", listOf(LatinGloss("Génetrix", "Mãe", "Aquela que deu à luz."), LatinGloss("ut digni efficiámur", "para que sejamos feitos dignos", null))),
            BilingualVerse("Oremos. Infundi, Senhor, em nossas almas a vossa graça, para que nós, que pela anunciação do Anjo conhecemos a encarnação de Cristo, vosso Filho, pela sua paixão e cruz sejamos conduzidos à glória da ressurreição. Por Cristo, nosso Senhor. Amém.", "Orémus. Grátiam tuam, quǽsumus, Dómine, méntibus nostris infúnde; ut qui, Ángelo nuntiánte, Christi Fílii tui incarnatiónem cognóvimus, per passiónem eius et crucem ad resurrectiónis glóriam perducámur. Per eúndem Christum Dóminum nostrum. Amen.", listOf(LatinGloss("infúnde", "infundi", null), LatinGloss("incarnatiónem", "encarnação", null), LatinGloss("perducámur", "sejamos conduzidos", null))),
        ),
        annotations = listOf(
            PrayerTermAnnotation(term = "Verbo se fez carne", origin = "Verbo traduz o grego Lógos, a Palavra eterna do Pai. Fazer-se carne significa assumir de verdade nossa natureza humana, sem deixar de ser Deus.", today = "Reconheço que Deus entrou na história concreta. Minha vida cotidiana, meu corpo e o cuidado com as pessoas são lugares de encontro com Cristo.", scriptureQuote = null, scriptureReference = "João 1,1–18", catechism = "Catecismo da Igreja Católica, 461–463"),
            PrayerTermAnnotation(term = "Faça-se em mim", origin = "O fiat de Maria não é resignação fatalista: é uma resposta livre e confiante à iniciativa de Deus, sustentada por sua graça.", today = "Peço discernimento para aceitar o bem que Deus me chama a realizar. Obedecer a Deus não é aceitar o abuso ou chamar de vontade divina toda injustiça.", scriptureQuote = null, scriptureReference = "Lucas 1,38", catechism = "Catecismo da Igreja Católica, 494; 2617"),
        ),
        source = "Compêndio do Catecismo da Igreja Católica, apêndice de orações comuns. Redação portuguesa adaptada; as indicações de Ave-Maria remetem à oração completa; doxologia final opcional não incluída.", context = "Tradicionalmente rezado de manhã, ao meio-dia e ao entardecer. Onde se lê Ave-Maria, reza-se a oração completa. Os versículos podem ser ditos por uma pessoa e respondidos por todos.",
        sourceUrls = listOf("https://www.vatican.va/archive/compendium_ccc/documents/archive_2005_compendium-ccc_po.html"),
        keywords = listOf(),
        fixedPrayer = null,
        latinSolo = null,
    )
    private fun prayer14() = TreasuryPrayer(
        id = "lembrai-vos", title = "Lembrai-vos", category = PrayerCategory.DISTRESS,
        summary = "O Memorare, uma súplica de confiança filial.", portuguese = "Lembrai-vos, ó piedosíssima Virgem Maria, que nunca se ouviu dizer que algum daqueles que recorreram à vossa proteção, imploraram a vossa assistência e reclamaram o vosso socorro fosse por vós desamparado. Animado com esta confiança, a vós, Virgem das virgens, como a mãe recorro; a vós venho e, gemendo sob o peso dos meus pecados, me prostro aos vossos pés. Não desprezeis as minhas súplicas, ó Mãe do Verbo, mas dignai-vos de as ouvir propícia e de me alcançar o que vos rogo. Amém.",
        latinTitle = "Memorare", latin = "Memoráre, o piíssima Virgo María, non esse audítum a sǽculo, quemquam ad tua curréntem præsídia, tua implorántem auxília, tua peténtem suffrágia esse derelíctum. Ego tali animátus confidéntia, ad te, Virgo Vírginum, Mater, curro; ad te vénio; coram te gemens peccátor assísto. Noli, Mater Verbi, verba mea despícere; sed audi propítia et exáudi. Amen.",
        verses = listOf(
            BilingualVerse("Lembrai-vos, ó piedosíssima Virgem Maria, que nunca se ouviu dizer que algum daqueles que recorreram à vossa proteção, imploraram a vossa assistência e reclamaram o vosso socorro fosse por vós desamparado.", "Memoráre, o piíssima Virgo María, non esse audítum a sǽculo, quemquam ad tua curréntem præsídia, tua implorántem auxília, tua peténtem suffrágia esse derelíctum.", listOf(LatinGloss("Memoráre", "lembrai-vos", null), LatinGloss("præsídia", "proteção", null), LatinGloss("suffrágia", "intercessão", "Aqui não significa votos eleitorais."), LatinGloss("derelíctum", "abandonado", null))),
            BilingualVerse("Animado com esta confiança, a vós, Virgem das virgens, como a mãe recorro; a vós venho e, gemendo sob o peso dos meus pecados, me prostro aos vossos pés.", "Ego tali animátus confidéntia, ad te, Virgo Vírginum, Mater, curro; ad te vénio; coram te gemens peccátor assísto.", listOf(LatinGloss("confidéntia", "confiança", null), LatinGloss("curro", "corro", "Imagem da pressa de um filho em buscar a mãe."), LatinGloss("peccátor", "pecador", null))),
            BilingualVerse("Não desprezeis as minhas súplicas, ó Mãe do Verbo, mas dignai-vos de as ouvir propícia e de me alcançar o que vos rogo. Amém.", "Noli, Mater Verbi, verba mea despícere; sed audi propítia et exáudi. Amen.", listOf(LatinGloss("Noli", "não", "Pedido negativo com infinitivo."), LatinGloss("Mater Verbi", "Mãe do Verbo", null), LatinGloss("propítia", "favorável", null))),
        ),
        annotations = listOf(
            PrayerTermAnnotation(term = "Mãe do Verbo", origin = "Verbo é o Filho eterno, a Palavra do Pai que se fez homem. A expressão une a profissão da divindade de Jesus à maternidade real de Maria.", today = "Dirijo a Maria um pedido que deve sempre me aproximar do seu Filho. Ela não é a origem da salvação: acolhe e nos apresenta o Salvador.", scriptureQuote = null, scriptureReference = "João 1,14; Lucas 1,43", catechism = "Catecismo da Igreja Católica, 466; 495"),
            PrayerTermAnnotation(term = "confiança", origin = "Confiar é entregar-se ao cuidado de Deus, inclusive quando o desfecho permanece desconhecido. A linguagem filial do Memorare expressa esperança, não uma garantia contratual.", today = "Posso pedir com insistência e dizer com honestidade o que desejo. Também peço força para atravessar a espera e acolher ajuda concreta.", scriptureQuote = null, scriptureReference = "Hebreus 4,16; Mateus 26,39", catechism = "Catecismo da Igreja Católica, 2734–2741"),
        ),
        source = "Compêndio do Catecismo da Igreja Católica, apêndice de orações comuns. Versão portuguesa devocional adaptada; autoria de São Bernardo não comprovada.", context = "Devoção mariana tradicional, frequentemente associada a São Bernardo, sem autoria comprovada dele. A confiança na intercessão de Maria não é promessa de que todo pedido será atendido da forma imaginada.",
        sourceUrls = listOf("https://www.vatican.va/archive/compendium_ccc/documents/archive_2005_compendium-ccc_po.html"),
        keywords = listOf(),
        fixedPrayer = null,
        latinSolo = null,
