    private fun prayer15() = TreasuryPrayer(
        id = "te-deum", title = "Te Deum", category = PrayerCategory.THANKSGIVING,
        summary = "O grande hino de louvor e ação de graças.", portuguese = "Nós Vos louvamos, ó Deus,\nnós Vos bendizemos, Senhor.\nToda a terra Vos adora,\nPai eterno e omnipotente.\nOs Anjos, os Céus\ne todas as Potestades,\nos Querubins e os Serafins\nVos aclamam sem cessar:\nSanto, Santo, Santo,\nSenhor Deus do Universo,\no céu e a terra proclamam a vossa glória.\nO coro glorioso dos Apóstolos,\na falange venerável dos Profetas,\no exército resplandecente dos Mártires\ncantam os vossos louvores.\nA santa Igreja anuncia por toda a terra\na glória do vosso nome:\nDeus de infinita majestade,\nPai, Filho e Espírito Santo.\nSenhor Jesus Cristo, Rei da glória,\nFilho do Eterno Pai,\npara salvar o homem, tomastes\na condição humana no seio da Virgem Maria.\nVós despedaçastes as cadeias da morte\ne abristes as portas do céu.\nVós estais sentado à direita de Deus,\nna glória do Pai,\ne de novo haveis de vir para julgar\nos vivos e os mortos.\nSocorrei os vossos servos, Senhor,\nque remistes com vosso Sangue precioso;\ne recebei-os na luz da glória,\nna assembleia dos vossos Santos.\nSalvai o vosso povo, Senhor,\ne abençoai a vossa herança;\nsede o seu pastor e guia através dos tempos\ne conduzi-o às fontes da vida eterna.\nNós Vos bendiremos todos os dias da nossa vida\ne louvaremos para sempre o vosso nome.\nDignai-Vos, Senhor, neste dia, livrar-nos do pecado.\nTende piedade de nós,\nSenhor, tende piedade de nós.\nDesça sobre nós a vossa misericórdia,\nPorque em Vós esperamos.\nEm Vós espero, meu Deus,\nnão serei confundido eternamente.",
        latinTitle = "Te Deum", latin = "Te Deum laudámus:\nte Dóminum confitémur.\nTe ætérnum Patrem,\nomnis terra venerátur.\ntibi omnes ángeli,\ntibi cæli\net univérsæ potestátes:\ntibi chérubim et séraphim\nincessábili voce proclámant:\nSanctus, Sanctus, Sanctus,\nDòminus Deus Sábaoth.\nPleni sunt cæli et terra\nmaiestátis glóriæ tuæ.\nTe gloriòsus\napostolòrum chorus,\nte prophetárum\nlaudábilis númerus,\nte mártyrum candidátus\nlaudat exércitus.\nTe per orbem terrarum\nsancta confitétur Ecclésia,\nPatrem imménsæ maiestátis;\nvenerándum tuum verum\net únicum Filium;\nSanctum quoque\nParáclitum Spíritum.\nTu rex glòriæ, Christe.\nTu Patris sempitérnus es Filius.\nTu, ad liberándum susceptúrus\nhóminem,\nnon horrúisti Virginis úterum.\nTu, devícto mortis acúleo,\naperuísti credéntibus regna cælórum.\nTu ad déxteram Dei sedes,\nin glória Patris.\nIudex créderis esse ventúrus.\nTe ergo quǽsumus,\ntuis famulis súbveni,\nquos pretiòso sanguine redemísti.\nÆtérna fac cum sanctis tuis\nin glória numerári.\nSalvum fac pópulum tuum, Dómine,\net bénedic hereditáti tuæ.\nEt rege eos, et extólle illos\nusque in ætérnum.\nPer síngulos dies benedícimus te;\net laudámus nomen tuum\nin sǽculum, et in sǽculum sǽculi.\nDignáre, Dòmine,\ndie isto sine peccáto nos custodíre.\nMiserére nostri, Dómine, miserére nostri.\nFiat misericórdia tua,\nDómine, super nos,\nquemádmodum sperávimus in te.\nIn te, Dómine, sperávi:\nnon confúndar in ætérnum.",
        verses = listOf(
            BilingualVerse("Nós Vos louvamos, ó Deus, nós Vos bendizemos, Senhor. Toda a terra Vos adora, Pai eterno e omnipotente.", "Te Deum laudámus: te Dóminum confitémur. Te ætérnum Patrem, omnis terra venerátur.", listOf(LatinGloss("Te Deum laudámus", "A vós, Deus, louvamos", null))),
            BilingualVerse("Os Anjos, os Céus e todas as Potestades, os Querubins e os Serafins Vos aclamam sem cessar:", "tibi omnes ángeli, tibi cæli et univérsæ potestátes: tibi chérubim et séraphim incessábili voce proclámant:", listOf(LatinGloss("ángeli", "anjos", null))),
            BilingualVerse("Santo, Santo, Santo, Senhor Deus do Universo, o céu e a terra proclamam a vossa glória.", "Sanctus, Sanctus, Sanctus, Dòminus Deus Sábaoth. Pleni sunt cæli et terra maiestátis glóriæ tuæ.", listOf(LatinGloss("Sanctus", "Santo", null))),
            BilingualVerse("O coro glorioso dos Apóstolos, a falange venerável dos Profetas, o exército resplandecente dos Mártires cantam os vossos louvores.", "Te gloriòsus apostolòrum chorus, te prophetárum laudábilis númerus, te mártyrum candidátus laudat exércitus.", listOf(LatinGloss("apostolòrum chorus", "coro dos apóstolos", null))),
            BilingualVerse("A santa Igreja anuncia por toda a terra a glória do vosso nome: Deus de infinita majestade, Pai, Filho e Espírito Santo.", "Te per orbem terrarum sancta confitétur Ecclésia, Patrem imménsæ maiestátis; venerándum tuum verum et únicum Filium; Sanctum quoque Paráclitum Spíritum.", listOf(LatinGloss("sancta confitétur Ecclésia", "a santa Igreja professa", null))),
            BilingualVerse("Senhor Jesus Cristo, Rei da glória, Filho do Eterno Pai, para salvar o homem, tomastes a condição humana no seio da Virgem Maria.", "Tu rex glòriæ, Christe. Tu Patris sempitérnus es Filius. Tu, ad liberándum susceptúrus hóminem, non horrúisti Virginis úterum.", listOf(LatinGloss("rex glòriæ", "Rei da glória", null))),
            BilingualVerse("Vós despedaçastes as cadeias da morte e abristes as portas do céu.", "Tu, devícto mortis acúleo, aperuísti credéntibus regna cælórum.", listOf(LatinGloss("devícto mortis acúleo", "vencido o aguilhão da morte", null))),
            BilingualVerse("Vós estais sentado à direita de Deus, na glória do Pai, e de novo haveis de vir para julgar os vivos e os mortos.", "Tu ad déxteram Dei sedes, in glória Patris. Iudex créderis esse ventúrus.", listOf(LatinGloss("ad déxteram Dei", "à direita de Deus", null))),
            BilingualVerse("Socorrei os vossos servos, Senhor, que remistes com vosso Sangue precioso; e recebei-os na luz da glória, na assembleia dos vossos Santos.", "Te ergo quǽsumus, tuis famulis súbveni, quos pretiòso sanguine redemísti. Ætérna fac cum sanctis tuis in glória numerári.", listOf(LatinGloss("famulis súbveni", "socorrei os servos", null))),
            BilingualVerse("Salvai o vosso povo, Senhor, e abençoai a vossa herança; sede o seu pastor e guia através dos tempos e conduzi-o às fontes da vida eterna.", "Salvum fac pópulum tuum, Dómine, et bénedic hereditáti tuæ. Et rege eos, et extólle illos usque in ætérnum.", listOf(LatinGloss("Salvum fac pópulum tuum", "salvai vosso povo", null))),
            BilingualVerse("Nós Vos bendiremos todos os dias da nossa vida e louvaremos para sempre o vosso nome.", "Per síngulos dies benedícimus te; et laudámus nomen tuum in sǽculum, et in sǽculum sǽculi.", listOf(LatinGloss("benedícimus te", "nós vos bendizemos", null))),
            BilingualVerse("Dignai-Vos, Senhor, neste dia, livrar-nos do pecado.", "Dignáre, Dòmine, die isto sine peccáto nos custodíre.", listOf(LatinGloss("sine peccáto", "sem pecado", null))),
            BilingualVerse("Tende piedade de nós, Senhor, tende piedade de nós.", "Miserére nostri, Dómine, miserére nostri.", listOf(LatinGloss("Miserére nostri", "tende piedade de nós", null))),
            BilingualVerse("Desça sobre nós a vossa misericórdia, Porque em Vós esperamos.", "Fiat misericórdia tua, Dómine, super nos, quemádmodum sperávimus in te.", listOf(LatinGloss("Fiat misericórdia tua", "venha a vossa misericórdia", null))),
            BilingualVerse("Em Vós espero, meu Deus, não serei confundido eternamente.", "In te, Dómine, sperávi: non confúndar in ætérnum.", listOf(LatinGloss("non confúndar in ætérnum", "não serei confundido eternamente", null))),
        ),
        annotations = listOf(
            PrayerTermAnnotation(term = "Potestades", origin = "Potestades é um dos nomes bíblicos para as criaturas espirituais que servem a Deus. O hino reúne a Igreja e os anjos num mesmo louvor, sem pretender descrever fisicamente o céu.", today = "Reconheço que meu louvor se une a uma realidade maior do que posso ver. A adoração é dirigida somente a Deus.", scriptureQuote = null, scriptureReference = "Colossenses 1,16; Isaías 6,2–3", catechism = "Catecismo da Igreja Católica, 328–336; 1138"),
        ),
        source = "Compêndio do Catecismo da Igreja Católica, apêndice de orações comuns. Texto português preservado conforme a edição da Santa Sé, com variantes de Portugal. Latim preservado com correção de “curo sanctis” para “cum sanctis”.", context = "Hino da tradição latina, sem atribuição histórica segura a Santo Ambrósio e Santo Agostinho. Reze-o inteiro em uma ocasião de gratidão; sua segunda parte pede auxílio e perseverança.",
