    private fun prayer16() = TreasuryPrayer(
        id = "benedictus", title = "Benedictus", category = PrayerCategory.WAKING,
        summary = "O cântico de Zacarias na oração da manhã.", portuguese = "Bendito o Senhor Deus de Israel\nque visitou e redimiu o seu povo,\ne nos deu um Salvador poderoso\nna casa de David, seu servo,\nconforme prometeu pela boca\ndos seus santos,\nos profetas dos tempos antigos,\npara nos libertar dos nossos inimigos,\ne das mãos daqueles que nos odeiam.\nPara mostrar a sua misericórdia a favor dos nossos pais,\nrecordando a sua sagrada aliança,\ne o juramento que fizera a Abraão,\nnosso pai,\nque nos havia de conceder esta graça:\nde O servirmos um dia, sem temor,\nlivres das mãos dos nossos inimigos,\nem santidade e justiça, na sua presença,\ntodos os dias da nossa vida.\nE tu, menino, serás chamado profeta\ndo Altíssimo,\nporque irás à sua frente a preparar os seus caminhos,\npara dar a conhecer ao seu povo a salvação\npela remissão dos seus pecados,\ngraças ao coração misericordioso\ndo nosso Deus,\nque das alturas nos visita\ncomo sol nascente,\npara iluminar os que jazem nas trevas\ne na sombra da morte\ne dirigir os nossos passos no caminho da paz.\nGlória ao Pai e ao Filho\ne ao Espírito Santo.\nComo era no princípio,\nagora e sempre. Ámen.",
        latinTitle = null, latin = null,
        verses = listOf(
        ),
        annotations = listOf(
            PrayerTermAnnotation(term = "sagrada aliança", origin = "Aliança é o vínculo de fidelidade que Deus estabelece com seu povo. O cântico recorda Abraão e anuncia a visita salvadora que se realiza em Jesus.", today = "Recordo que a fé começa na fidelidade de Deus, não na perfeição dos meus sentimentos. Peço perseverança para responder com fidelidade.", scriptureQuote = null, scriptureReference = "Lucas 1,72–73; Gênesis 17,1–8", catechism = "Catecismo da Igreja Católica, 59–64; 422"),
        ),
        source = "Compêndio do Catecismo da Igreja Católica, apêndice de orações comuns. Texto português preservado conforme a edição da Santa Sé, com variantes de Portugal.", context = "Lucas 1,68–79, seguido da doxologia. Usado nas Laudes, celebra a fidelidade de Deus à aliança e a missão de João Batista. O sol nascente é uma imagem de Cristo, não uma adoração do astro.",
        sourceUrls = listOf("https://www.vatican.va/archive/compendium_ccc/documents/archive_2005_compendium-ccc_po.html"),
