            PrayerTermAnnotation(term = "descanso", origin = "A imagem bíblica do repouso expressa a vida em comunhão com Deus. Rezar pelos mortos não é tentar obter mensagens deles, mas confiá-los à misericórdia do Senhor.", today = "Posso recordar o nome de quem morreu e oferecer minha oração com esperança. O luto tem seu tempo e não é sinal de falta de fé.", scriptureQuote = null, scriptureReference = "2 Macabeus 12,44–46; Apocalipse 14,13", catechism = "Catecismo da Igreja Católica, 958; 1032"),
