    private fun prayer24() = TreasuryPrayer(
        id = "veni-sancte-spiritus", title = "Vinde, Espírito Santo — sequência", category = PrayerCategory.WAKING,
        summary = "A sequência de Pentecostes, estrofe por estrofe.", portuguese = "Vinde, Espírito Santo, e enviai do céu um raio de vossa luz. Vinde, pai dos pobres; vinde, doador dos dons; vinde, luz dos corações. Consolador perfeito, doce hóspede da alma, suave refrigério. No trabalho, descanso; no calor, frescor; no pranto, consolo. Ó luz bem-aventurada, enchei o íntimo do coração de vossos fiéis. Sem a vossa força, nada há no ser humano, nada há de inocente. Lavai o que está manchado, regai o que está árido, curai o que está ferido. Dobrai o que é rígido, aquecei o que está frio, guiai o que se desviou. Dai a vossos fiéis, que em vós confiam, os sete dons sagrados. Dai o mérito da virtude, dai uma morte de salvação, dai a alegria eterna. Amém.",
        latinTitle = "Veni Sancte Spiritus", latin = "Veni, Sancte Spíritus, et emítte cǽlitus lucis tuæ rádium. Veni, pater páuperum, veni, dator múnerum, veni, lumen córdium. Consolátor óptime, dulcis hospes ánimæ, dulce refrigérium. In labóre réquies, in æstu tempéries, in fletu solácium. O lux beatíssima, reple cordis íntima tuórum fidélium. Sine tuo númine, nihil est in hómine, nihil est innóxium. Lava quod est sórdidum, riga quod est áridum, sana quod est sáucium. Flecte quod est rígidum, fove quod est frígidum, rege quod est dévium. Da tuis fidélibus, in te confidéntibus, sacrum septenárium. Da virtútis méritum, da salútis éxitum, da perénne gáudium. Amen.",
        verses = listOf(
            BilingualVerse("Vinde, Espírito Santo, e enviai do céu um raio de vossa luz.", "Veni, Sancte Spíritus, et emítte cǽlitus lucis tuæ rádium.", listOf(LatinGloss("Veni", "vinde", null), LatinGloss("emítte", "enviai", null), LatinGloss("cǽlitus", "do céu", null))),
            BilingualVerse("Vinde, pai dos pobres; vinde, doador dos dons; vinde, luz dos corações.", "Veni, pater páuperum, veni, dator múnerum, veni, lumen córdium.", listOf(LatinGloss("pater páuperum", "pai dos pobres", null), LatinGloss("dator múnerum", "doador dos dons", null))),
            BilingualVerse("Consolador perfeito, doce hóspede da alma, suave refrigério.", "Consolátor óptime, dulcis hospes ánimæ, dulce refrigérium.", listOf(LatinGloss("hospes ánimæ", "hóspede da alma", null), LatinGloss("refrigérium", "refrigério", null))),
            BilingualVerse("No trabalho, descanso; no calor, frescor; no pranto, consolo.", "In labóre réquies, in æstu tempéries, in fletu solácium.", listOf(LatinGloss("réquies", "descanso", null), LatinGloss("solácium", "consolo", null))),
            BilingualVerse("Ó luz bem-aventurada, enchei o íntimo do coração de vossos fiéis.", "O lux beatíssima, reple cordis íntima tuórum fidélium.", listOf(LatinGloss("reple", "enchei", null), LatinGloss("cordis íntima", "o íntimo do coração", null))),
            BilingualVerse("Sem a vossa força, nada há no ser humano, nada há de inocente.", "Sine tuo númine, nihil est in hómine, nihil est innóxium.", listOf(LatinGloss("Sine", "sem", null), LatinGloss("númine", "força divina", null), LatinGloss("nihil", "nada", null))),
            BilingualVerse("Lavai o que está manchado, regai o que está árido, curai o que está ferido.", "Lava quod est sórdidum, riga quod est áridum, sana quod est sáucium.", listOf(LatinGloss("Lava", "lavai", null), LatinGloss("riga", "regai", null), LatinGloss("sana", "curai", null))),
            BilingualVerse("Dobrai o que é rígido, aquecei o que está frio, guiai o que se desviou.", "Flecte quod est rígidum, fove quod est frígidum, rege quod est dévium.", listOf(LatinGloss("Flecte", "dobrai", null), LatinGloss("fove", "aquecei", null), LatinGloss("rege", "guiai", null))),
            BilingualVerse("Dai a vossos fiéis, que em vós confiam, os sete dons sagrados.", "Da tuis fidélibus, in te confidéntibus, sacrum septenárium.", listOf(LatinGloss("Da", "dai", null), LatinGloss("sacrum septenárium", "os sete dons sagrados", null))),
            BilingualVerse("Dai o mérito da virtude, dai uma morte de salvação, dai a alegria eterna. Amém.", "Da virtútis méritum, da salútis éxitum, da perénne gáudium. Amen.", listOf(LatinGloss("salútis éxitum", "desfecho de salvação", "Uma boa morte na graça de Deus."), LatinGloss("perénne gáudium", "alegria eterna", null))),
        ),
        annotations = listOf(
            PrayerTermAnnotation(term = "sete dons", origin = "A tradição cristã reconhece em Isaías os dons do Espírito: sabedoria, entendimento, conselho, fortaleza, ciência, piedade e temor de Deus. Não são talentos para competição espiritual.", today = "Peço docilidade para discernir, coragem para o bem e reverência amorosa. Os dons amadurecem na caridade cotidiana e no serviço.", scriptureQuote = null, scriptureReference = "Isaías 11,1–3; Gálatas 5,22–23", catechism = "Catecismo da Igreja Católica, 1830–1832"),
        ),
        source = "Compêndio do Catecismo da Igreja Católica, apêndice de orações comuns. Latim da sequência, com correção de “sáueium” para “sáucium”; tradução portuguesa editorial.", context = "Invoca o Espírito como luz, consolo e força de conversão. A tradução portuguesa desta entrada é editorial e literal, para manter correspondência com cada estrofe latina; não substitui o texto cantado na liturgia.",
