    private fun prayer25() = TreasuryPrayer(
        id = "veni-creator", title = "Vinde, Espírito Criador", category = PrayerCategory.WAKING,
        summary = "O hino ao Espírito que renova a criação.", portuguese = "Vinde, Espírito Criador, visitai as almas dos vossos; enchei de graça do alto os corações que criastes. Vós que sois chamado Paráclito, dom do Deus Altíssimo, fonte viva, fogo, amor e unção espiritual. Vós sois sete vezes generoso em dons, dedo da direita do Pai, promessa verdadeira do Pai, que enriqueceis de palavra os lábios. Acendei a luz nos sentidos, infundi o amor nos corações; fortalecei com força constante a fraqueza de nosso corpo. Afastai para longe o inimigo e dai-nos sem demora a paz; sob vossa guia, evitemos todo mal. Por vós conheçamos o Pai, conheçamos também o Filho; e creiamos em vós, Espírito de ambos, em todo tempo. Glória seja a Deus Pai e ao Filho, que ressuscitou dos mortos, e ao Paráclito, pelos séculos dos séculos. Amém.",
        latinTitle = "Veni Creator Spiritus", latin = "Veni, creátor Spíritus, mentes tuórum vísita, imple supérna grátia, quæ tu creásti péctora. Qui díceris Paráclitus, altíssimi donum Dei, fons vivus, ignis, cáritas, et spiritális únctio. Tu septifórmis múnere, dígitus patérnæ déxteræ, tu rite promíssum Patris, sermóne ditans gúttura. Accénde lumen sénsibus, infúnde amórem córdibus, infírma nostri córporis virtúte firmans pérpeti. Hostem repéllas lóngius pacémque dones prótinus; ductóre sic te prǽvio vitémus omne nóxium. Per te sciámus da Patrem, noscámus atque Fílium, teque utriúsque Spíritum credámus omni témpore. Deo Patri sit glória, et Fílio, qui a mórtuis surréxit, ac Paráclito, in sæculórum sǽcula. Amen.",
        verses = listOf(
            BilingualVerse("Vinde, Espírito Criador, visitai as almas dos vossos; enchei de graça do alto os corações que criastes.", "Veni, creátor Spíritus, mentes tuórum vísita, imple supérna grátia, quæ tu creásti péctora.", listOf(LatinGloss("creátor", "criador", null), LatinGloss("vísita", "visitai", null), LatinGloss("imple", "enchei", null))),
            BilingualVerse("Vós que sois chamado Paráclito, dom do Deus Altíssimo, fonte viva, fogo, amor e unção espiritual.", "Qui díceris Paráclitus, altíssimi donum Dei, fons vivus, ignis, cáritas, et spiritális únctio.", listOf(LatinGloss("Paráclitus", "Paráclito", "Consolador e defensor."), LatinGloss("fons vivus", "fonte viva", null), LatinGloss("cáritas", "amor", null))),
            BilingualVerse("Vós sois sete vezes generoso em dons, dedo da direita do Pai, promessa verdadeira do Pai, que enriqueceis de palavra os lábios.", "Tu septifórmis múnere, dígitus patérnæ déxteræ, tu rite promíssum Patris, sermóne ditans gúttura.", listOf(LatinGloss("septifórmis múnere", "sete vezes generoso em dons", null), LatinGloss("sermóne", "de palavra", null))),
            BilingualVerse("Acendei a luz nos sentidos, infundi o amor nos corações; fortalecei com força constante a fraqueza de nosso corpo.", "Accénde lumen sénsibus, infúnde amórem córdibus, infírma nostri córporis virtúte firmans pérpeti.", listOf(LatinGloss("Accénde", "acendei", null), LatinGloss("infúnde amórem", "infundi o amor", null))),
            BilingualVerse("Afastai para longe o inimigo e dai-nos sem demora a paz; sob vossa guia, evitemos todo mal.", "Hostem repéllas lóngius pacémque dones prótinus; ductóre sic te prǽvio vitémus omne nóxium.", listOf(LatinGloss("pacémque", "e a paz", null), LatinGloss("vitémus", "evitemos", null))),
            BilingualVerse("Por vós conheçamos o Pai, conheçamos também o Filho; e creiamos em vós, Espírito de ambos, em todo tempo.", "Per te sciámus da Patrem, noscámus atque Fílium, teque utriúsque Spíritum credámus omni témpore.", listOf(LatinGloss("Per te", "por vós", null), LatinGloss("noscámus", "conheçamos", null), LatinGloss("utriúsque", "de ambos", null))),
            BilingualVerse("Glória seja a Deus Pai e ao Filho, que ressuscitou dos mortos, e ao Paráclito, pelos séculos dos séculos. Amém.", "Deo Patri sit glória, et Fílio, qui a mórtuis surréxit, ac Paráclito, in sæculórum sǽcula. Amen.", listOf(LatinGloss("sit glória", "seja a glória", null), LatinGloss("a mórtuis", "dos mortos", null))),
        ),
        annotations = listOf(
            PrayerTermAnnotation(term = "Paráclito", origin = "Do grego paráklētos: alguém chamado para estar ao lado, defensor e consolador. Jesus usa esse nome ao prometer o Espírito Santo aos discípulos.", today = "Peço ao Espírito luz para a verdade e força para testemunhar com amor. Sua consolação não é somente emoção agradável: também sustenta a fidelidade difícil.", scriptureQuote = null, scriptureReference = "João 14,16–17.26; 15,26", catechism = "Catecismo da Igreja Católica, 692; 1433"),
        ),
        source = "Compêndio do Catecismo da Igreja Católica, apêndice de orações comuns. Latim com correção de “Parác1ito” para “Paráclito”; tradução portuguesa editorial. Não se usa a versão portuguesa equivocadamente rotulada no apêndice.", context = "Hino latino tradicional, distinto da sequência Veni Sancte Spiritus. Esta tradução literal acompanha as sete estrofes; o texto não é apresentado como versão litúrgica aprovada para canto.",
