    private fun prayer28() = TreasuryPrayer(
        id = "credo-niceno", title = "Credo Niceno-Constantinopolitano", category = PrayerCategory.MARIAN,
        summary = "O símbolo da fé professado na Missa.", portuguese = "Creio em um só Deus, Pai todo-poderoso, criador do céu e da terra, de todas as coisas visíveis e invisíveis. Creio em um só Senhor, Jesus Cristo, Filho Unigênito de Deus, nascido do Pai antes de todos os séculos: Deus de Deus, luz da luz, Deus verdadeiro de Deus verdadeiro, gerado, não criado, consubstancial ao Pai. Por ele todas as coisas foram feitas. E por nós, homens, e para nossa salvação, desceu dos céus: e se encarnou pelo Espírito Santo, no seio da Virgem Maria, e se fez homem. Também por nós foi crucificado sob Pôncio Pilatos; padeceu e foi sepultado. Ressuscitou ao terceiro dia, conforme as Escrituras, e subiu aos céus, onde está sentado à direita do Pai. E de novo há de vir, em sua glória, para julgar os vivos e os mortos; e o seu Reino não terá fim. Creio no Espírito Santo, Senhor que dá a vida, e procede do Pai e do Filho; e com o Pai e o Filho é adorado e glorificado: ele que falou pelos profetas. Creio na Igreja, una, santa, católica e apostólica. Professo um só batismo para remissão dos pecados. E espero a ressurreição dos mortos e a vida do mundo que há de vir. Amém.",
        latinTitle = "Symbolum Nicænum-Constantinopolitanum", latin = "Credo in unum Deum, Patrem omnipoténtem, factórem cæli et terræ, visibílium ómnium et invisibílium. Et in unum Dóminum Iesum Christum, Fílium Dei Unigénitum, et ex Patre natum ante ómnia sǽcula. Deum de Deo, lumen de lúmine, Deum verum de Deo vero, génitum, non factum, consubstantiálem Patri. Per quem ómnia facta sunt. Qui propter nos hómines et propter nostram salútem descéndit de cælis. Et incarnátus est de Spíritu Sancto ex María Vírgine, et homo factus est. Crucifíxus étiam pro nobis sub Póntio Piláto; passus et sepúltus est. Et resurréxit tértia die, secúndum Scriptúras, et ascéndit in cælum, sedet ad déxteram Patris. Et íterum ventúrus est cum glória, iudicáre vivos et mórtuos, cuius regni non erit finis. Et in Spíritum Sanctum, Dóminum et vivificántem, qui ex Patre Filióque procédit. Qui cum Patre et Fílio simul adorátur et conglorificátur: qui locútus est per prophétas. Et unam, sanctam, cathólicam et apostólicam Ecclésiam. Confíteor unum baptísma in remissiónem peccatórum. Et exspécto resurrectiónem mortuórum et vitam ventúri sǽculi. Amen.",
        verses = listOf(
            BilingualVerse("Creio em um só Deus, Pai todo-poderoso, criador do céu e da terra, de todas as coisas visíveis e invisíveis.", "Credo in unum Deum, Patrem omnipoténtem, factórem cæli et terræ, visibílium ómnium et invisibílium.", listOf(LatinGloss("in unum Deum", "em um só Deus", null), LatinGloss("factórem", "criador", null))),
            BilingualVerse("Creio em um só Senhor, Jesus Cristo, Filho Unigênito de Deus, nascido do Pai antes de todos os séculos:", "Et in unum Dóminum Iesum Christum, Fílium Dei Unigénitum, et ex Patre natum ante ómnia sǽcula.", listOf(LatinGloss("Unigénitum", "Unigênito", null), LatinGloss("ante ómnia sǽcula", "antes de todos os séculos", null))),
            BilingualVerse("Deus de Deus, luz da luz, Deus verdadeiro de Deus verdadeiro, gerado, não criado, consubstancial ao Pai.", "Deum de Deo, lumen de lúmine, Deum verum de Deo vero, génitum, non factum, consubstantiálem Patri.", listOf(LatinGloss("génitum", "gerado", null), LatinGloss("non factum", "não criado", null), LatinGloss("consubstantiálem Patri", "consubstancial ao Pai", null))),
            BilingualVerse("Por ele todas as coisas foram feitas.", "Per quem ómnia facta sunt.", listOf(LatinGloss("Per quem", "por ele", null), LatinGloss("ómnia", "todas as coisas", null))),
            BilingualVerse("E por nós, homens, e para nossa salvação, desceu dos céus: e se encarnou pelo Espírito Santo, no seio da Virgem Maria, e se fez homem.", "Qui propter nos hómines et propter nostram salútem descéndit de cælis. Et incarnátus est de Spíritu Sancto ex María Vírgine, et homo factus est.", listOf(LatinGloss("propter nostram salútem", "para nossa salvação", null), LatinGloss("homo factus est", "fez-se homem", null))),
            BilingualVerse("Também por nós foi crucificado sob Pôncio Pilatos; padeceu e foi sepultado.", "Crucifíxus étiam pro nobis sub Póntio Piláto; passus et sepúltus est.", listOf(LatinGloss("pro nobis", "por nós", null), LatinGloss("passus", "padeceu", null))),
            BilingualVerse("Ressuscitou ao terceiro dia, conforme as Escrituras, e subiu aos céus, onde está sentado à direita do Pai.", "Et resurréxit tértia die, secúndum Scriptúras, et ascéndit in cælum, sedet ad déxteram Patris.", listOf(LatinGloss("secúndum Scriptúras", "conforme as Escrituras", null), LatinGloss("ad déxteram Patris", "à direita do Pai", null))),
            BilingualVerse("E de novo há de vir, em sua glória, para julgar os vivos e os mortos; e o seu Reino não terá fim.", "Et íterum ventúrus est cum glória, iudicáre vivos et mórtuos, cuius regni non erit finis.", listOf(LatinGloss("íterum", "de novo", null), LatinGloss("non erit finis", "não terá fim", null))),
            BilingualVerse("Creio no Espírito Santo, Senhor que dá a vida, e procede do Pai e do Filho; e com o Pai e o Filho é adorado e glorificado: ele que falou pelos profetas.", "Et in Spíritum Sanctum, Dóminum et vivificántem, qui ex Patre Filióque procédit. Qui cum Patre et Fílio simul adorátur et conglorificátur: qui locútus est per prophétas.", listOf(LatinGloss("vivificántem", "que dá a vida", null), LatinGloss("Filióque", "e do Filho", "A terminação que significa e."), LatinGloss("procédit", "procede", null))),
            BilingualVerse("Creio na Igreja, una, santa, católica e apostólica.", "Et unam, sanctam, cathólicam et apostólicam Ecclésiam.", listOf(LatinGloss("unam", "una", null), LatinGloss("apostólicam", "apostólica", null))),
            BilingualVerse("Professo um só batismo para remissão dos pecados.", "Confíteor unum baptísma in remissiónem peccatórum.", listOf(LatinGloss("Confíteor", "professo", "Aqui é profissão da fé, não confissão de culpa."), LatinGloss("in remissiónem", "para remissão", null))),
            BilingualVerse("E espero a ressurreição dos mortos e a vida do mundo que há de vir. Amém.", "Et exspécto resurrectiónem mortuórum et vitam ventúri sǽculi. Amen.", listOf(LatinGloss("exspécto", "espero", null), LatinGloss("ventúri sǽculi", "do mundo que há de vir", null))),
        ),
        annotations = listOf(
            PrayerTermAnnotation(term = "consubstancial ao Pai", origin = "Consubstancial traduz o grego homoousios: da mesma substância ou natureza. O Filho não é uma criatura superior; é verdadeiramente Deus, distinto do Pai como pessoa.", today = "Ao dizer essas palavras, confio que é o próprio Deus quem vem salvar-nos em Jesus. A comunhão com Cristo nos introduz na vida do Pai.", scriptureQuote = null, scriptureReference = "João 1,1; 10,30; Hebreus 1,3", catechism = "Catecismo da Igreja Católica, 242; 253–255"),
